import{_ as a,a0 as p,w as d,s as n,I as o,x as t,a1 as l,A as s,ao as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const g=JSON.parse('{"title":"如何在 VirtualBox 上安裝並使用 FreeDOS？ | LCTT x X-CMD","titleTemplate":false,"description":"如何在 VirtualBox 上安裝並使用 FreeDOS？ | LCTT (201812) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 VirtualBox 上安裝並使用 FreeDOS？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 VirtualBox 上安裝並使用 FreeDOS？ | LCTT (201812) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201812/20180826 How to Install and Use FreeDOS on VirtualBox","title":"如何在 VirtualBox 上安裝並使用 FreeDOS？","tag":"201812","desc":""},"relativePath":"201812/20180826 How to Install and Use FreeDOS on VirtualBox.md","filePath":"[post].md"}'),u={name:"201812/20180826 How to Install and Use FreeDOS on VirtualBox.md"};function m(f,e,S,D,x,w){const r=p("Link");return d(),n("div",null,[e[37]||(e[37]=o("h1",{id:"如何在-virtualbox-上安裝並使用-freedos",tabindex:"-1"},[t("如何在 VirtualBox 上安裝並使用 FreeDOS？ "),o("a",{class:"header-anchor",href:"#如何在-virtualbox-上安裝並使用-freedos","aria-label":"Permalink to “如何在 VirtualBox 上安裝並使用 FreeDOS？”"},"​")],-1)),e[38]||(e[38]=o("blockquote",null,[o("p",null,"這份指南將帶你如何一步一步在 Linux 平台下利用 VirtualBox 安裝 FreeDOS。")],-1)),e[39]||(e[39]=o("h3",{id:"linux-下藉助-virtualbox-安裝-freedos",tabindex:"-1"},[t("Linux 下藉助 VirtualBox 安裝 FreeDOS "),o("a",{class:"header-anchor",href:"#linux-下藉助-virtualbox-安裝-freedos","aria-label":"Permalink to “Linux 下藉助 VirtualBox 安裝 FreeDOS”"},"​")],-1)),o("ul",null,[o("li",null,[l(r,{href:"https://www.youtube.com/p1MegqzFAqA"},{default:s(()=>[...e[0]||(e[0]=[t("How to Install FreeDOS in Linux using Virtual Box",-1)])]),_:1})])]),o("p",null,[e[5]||(e[5]=t("2017 年的 11 月份，我",-1)),l(r,{href:"https://itsfoss.com/interview-freedos-jim-hall/"},{default:s(()=>[...e[1]||(e[1]=[t("採訪了 Jim Hall",-1)])]),_:1}),e[6]||(e[6]=t(" 關於 ",-1)),l(r,{href:"http://www.freedos.org/"},{default:s(()=>[...e[2]||(e[2]=[t("FreeDOS 項目",-1)])]),_:1}),e[7]||(e[7]=t(" 背後的歷史故事。今天，我將告訴你如何安裝並使用 FreeDOS。需要注意到是：我將在 ",-1)),l(r,{href:"https://solus-project.com/home/"},{default:s(()=>[...e[3]||(e[3]=[t("Solus",-1)])]),_:1}),e[8]||(e[8]=t("（一種針對家庭用户的 Linux 桌面發行版）下使用 5.2.14 版本的 ",-1)),l(r,{href:"https://www.virtualbox.org/"},{default:s(()=>[...e[4]||(e[4]=[t("VirtualBox",-1)])]),_:1}),e[9]||(e[9]=t(" 來完成這些操作。",-1))]),e[40]||(e[40]=i('<blockquote><p>注意：在本教程我將使用 Solus 作為主機系統因為它很容易設置。另一個你需要注意的事情是 Solus 的軟件中心有兩個版本的 VirtualBox：<code>virtualbox</code> 和 <code>virtualbox-current</code>。Solus 會讓你選擇是使用 linux-lts 內核還是 linux-current 內核。最終區別就是，<code>virtualbox</code> 適用於 linux-lts 而 <code>virtualbx-current</code> 適用於 linux-current。</p></blockquote><h4 id="第一步-–-創建新的虛擬機" tabindex="-1">第一步 – 創建新的虛擬機 <a class="header-anchor" href="#第一步-–-創建新的虛擬機" aria-label="Permalink to “第一步 – 創建新的虛擬機”">​</a></h4><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2018/07/freedos-tutorial-1.jpg?w=787&amp;ssl=1" alt=""></p><p>當你打開 VirtualBox，點擊 “New” 按鈕來新建一個虛擬機。你可以自定義這台虛擬機的名字，我將它命名為 “FreeDOS”。你也可以在標註欄內指明你正在安裝的 FreeDOS 的版本。你還需要選擇你將要安裝的操作系統的類型和版本。選擇 “Other” 下的 “DOS”。</p><h4 id="第二步-–-設置內存大小" tabindex="-1">第二步 – 設置內存大小 <a class="header-anchor" href="#第二步-–-設置內存大小" aria-label="Permalink to “第二步 – 設置內存大小”">​</a></h4><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2018/07/freedos-tutorial-2.jpg?w=792&amp;ssl=1" alt=""></p><p>下一個對話框會問你要給 FreeDOS 主機分配多少可用的內存空間。默認分配 32 MB。不必更改它。在 DOS 系統盛行的年代，32 MB 大小的內存對於一台搭載 FreeDOS 的機器已經很足夠了。如果你有需要，你可以通過對你針對 FreeDOS 新建的虛擬機右鍵並選擇 “Setting -&gt; Symtem” 來增加內存。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2018/07/freedos-tutorial-3.jpg?w=797&amp;ssl=1" alt=""></p><h4 id="第三步-–-創建虛擬硬盤" tabindex="-1">第三步 – 創建虛擬硬盤 <a class="header-anchor" href="#第三步-–-創建虛擬硬盤" aria-label="Permalink to “第三步 – 創建虛擬硬盤”">​</a></h4><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2018/07/freedos-tutorial-4.jpg?w=684&amp;ssl=1" alt=""></p><p>下一步，你會被要求創建一個虛擬硬盤用來存儲 FreeDOS 和它的文件。如果你還沒有創建，只需要點擊 “Create”。</p><p>下一個對話框會問你想用什麼磁盤文件類型。默認的類型 (VirtualBox Disk Image) 效果就挺好。點擊 “Next”。</p><p>下一個你遇到的問題是你想虛擬硬盤以何種方式創建。你是否希望虛擬硬盤佔據的空間剛開始很小然後會隨着你創建文件和安裝軟件逐漸增加直至達到你設置的上限？那麼選擇動態分配。如果你更喜歡虛擬硬盤 (VHD) 按照既定大小直接創建，選擇固定大小即可。如果你不打算使用整個 VHD 或者你的硬盤空餘空間不是太足夠，那麼動態分配是個很不錯的分配方式。（需要注意的是，動態分配的虛擬硬盤佔據的空間會隨着你增加文件而增加，但不會因為你刪除文件而變小） 我個人更喜歡動態分配，但你可以根據實際需要來選擇最合適你的分配類型然後點擊 “Next”。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2018/07/freedos-tutorial-6.jpg?w=705&amp;ssl=1" alt=""></p><p>現在，你可以選擇虛擬磁盤的大小和位置。500 MB 已經很足夠了。需要注意的是很多你之後用到的程序都是基於文本的，這意味着它們佔據的空間非常小。在你做好這些調整後，點擊 “Create”。</p><h4 id="第四步-–-關聯-iso-文件" tabindex="-1">第四步 – 關聯 .iso 文件 <a class="header-anchor" href="#第四步-–-關聯-iso-文件" aria-label="Permalink to “第四步 – 關聯 .iso 文件”">​</a></h4>',16)),o("p",null,[e[11]||(e[11]=t("在我們繼續之前，你需要",-1)),l(r,{href:"http://www.freedos.org/download/"},{default:s(()=>[...e[10]||(e[10]=[t("下載",-1)])]),_:1}),e[12]||(e[12]=t(" FreeDOS 的 .iso 文件。你需要選擇 CDROM 格式的 “standard” 安裝程序。",-1))]),e[41]||(e[41]=i('<p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2018/07/freedos-tutorial-7.jpg?w=800&amp;ssl=1" alt=""></p><p>當文件下載完畢後，返回到 VirtualBox。選中你的虛擬機並打開設置。你可以通過對虛擬機右鍵並選中 “Setting” 或者選中虛擬機並點擊 “Setting” 按鈕。</p><p>接下來，點擊 “Storage” 選項卡。在 “Storage Devices” 下面，選中 CD 圖標。(它應該會在圖標旁邊顯示 “Empty”。) 在右邊的 “Attribute” 面板，點中 CD 圖標然後在對應路徑選中你剛下載的 .iso 文件。</p><blockquote><p>提示：通常，在你通過 VirtualBox 安裝完一個操作系統後你就可以刪除對應的 .iso 文件了。但這並不適合 FreeDOS 。如果你想通過 FreeDOS 的包管理器來安裝應用程序，你需要這個 .iso 文件。我通常會讓這個 .iso 文件連接到虛擬機以便我安裝一些程序。如果你也這麼做了，你必須要確認下你讓 FreeDOS 虛擬機每次啓動的時候是從硬盤啓動因為虛擬機的默認設置是從已關聯的 .iso 文件啓動。如果你忘了關聯 .iso 文件，也不用擔心。你可以通過選擇 FreeDOS 虛擬機窗口上方的 “Devices” 來關聯。然後就會發現 .iso 文件列在 “Optical Drives”。</p></blockquote><h4 id="第五步-–-安裝-freedos" tabindex="-1">第五步 – 安裝 FreeDOS <a class="header-anchor" href="#第五步-–-安裝-freedos" aria-label="Permalink to “第五步 – 安裝 FreeDOS”">​</a></h4><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2018/07/freedos-tutorial-8.png?w=789&amp;ssl=1" alt=""></p><p>既然我們已經完成了所有的準備工作，讓我們來開始安裝 FreeDOS 吧。</p><p>首先，你需要知道關於最新版本的 VirtualBox 的一個 bug。當我們創建好虛擬硬盤然後選中 “Install to harddisk” 後，如果你開啓虛擬機你會發現在 FreeDOS 的歡迎界面出現過後就是不斷滾動無羣無盡的機器代碼。我最近就遇到過這個問題而且不管是 Linux 還是 Windows 平台的 VirtualBox 都會碰到這個問題。（我知道解決辦法。）</p><p>為了避開這個問題，你需要做一個簡單的修改。當你看到 FreeDOS 的歡迎界面的時候，按下 Tab 鍵。（確認 “Install to harddrive” 已經選中。）在 “fdboot.img” 之後輸入 <code>raw</code> 然後按下回車鍵。接下來就會啓動 FreeDOS 的安裝程序。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2018/07/freedos-tutorial-9.png?w=748&amp;ssl=1" alt=""></p><p>安裝程序會首先處理你的虛擬磁盤的格式化。當格式化完成後，安裝程序會重啓。當 FreeDOS 的歡迎界面再次出現的時候，你必須重新輸入 <code>raw</code> 就像你之前輸入的內容那樣。</p><p>要確保在安裝過程中你遇到的所有問題你選的都是 “Yes”。但也要注意有一個很重要的問題：“What FreeDOS packages do you want to install?” 的答案並不是 “Yes” 或者 “No”。答案有兩個選擇分別是 “Base packages” 和 “Full installation”。“Base packages” 針對的是想體驗類似原始的 MS-DOS 環境的人羣。“Full installation” 則包括了一系列工具和實用的程序來提升 DOS。</p><p>在整個安裝過程的最後，你可以選擇重啓或者繼續停留在 DOS。選擇“reboot”。</p><h4 id="第六步-–-設置網絡" tabindex="-1">第六步 – 設置網絡 <a class="header-anchor" href="#第六步-–-設置網絡" aria-label="Permalink to “第六步 – 設置網絡”">​</a></h4><p>不同於原始的 DOS，FreeDOS 可以訪問互聯網。你可以安裝新的軟件包或者更新你已經安裝的軟件包。要想使用網絡，你還需要在 FreeDOS 安裝些應用程序。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2018/07/freedos-tutorial-10.png?w=792&amp;ssl=1" alt=""></p><p>首先，啓動進入你新創建的 FreeDOS 虛擬機。在 FreeDOS 的選擇界面，選中 “Boot from System harddrive”。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2018/07/freedos-tutorial-11.png?w=739&amp;ssl=1" alt=""></p><p>現在，你可以通過輸入 <code>fdimples</code> 來訪問 FreeDOS 的軟件包管理工具。你也可以藉助方向鍵來瀏覽軟件包管理器，然後用空格鍵選擇類別或者軟件包。在 “Networking” 類別中，你需要選中 <code>fdnet</code>。FreeDOS project 推薦也安裝 <code>mtcp</code> 和 <code>wget</code>。多次點擊 Tab 鍵直到選中 “OK” 然後在按下回車鍵。安裝完成後，輸入 <code>reboot</code> 並按下回車鍵確認執行。系統重啓後，引導你的系統驅動。如果網絡安裝成功的話，你會在終端看到一些關於你的網絡信息的新消息。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2018/07/freedos-tutorial-12.png?w=744&amp;ssl=1" alt=""></p><p>注意：</p><p>有時候 VirtualBox 的默認設置並沒有生效。如果遇到這種情況，先關閉你的 FreeDOS 虛擬機窗口。在 VirtualBox 主界面右鍵你的虛擬機並選中 “Setting”。VirtualBox 默認的網絡設置是 “NAT”。將它改為 “Bridged Adapter” 後再嘗試安裝 FreeDOS 的軟件包。現在就應該能正常運作了。</p><h4 id="第七步-–-freedos-的基本使用" tabindex="-1">第七步 – FreeDOS 的基本使用 <a class="header-anchor" href="#第七步-–-freedos-的基本使用" aria-label="Permalink to “第七步 – FreeDOS 的基本使用”">​</a></h4><h5 id="常見命令" tabindex="-1">常見命令 <a class="header-anchor" href="#常見命令" aria-label="Permalink to “常見命令”">​</a></h5><p>既然你已經成功安裝了 FreeDOS，讓我們來看些基礎命令。如果你已經在 Windows 平台使用過命令提示符，那麼你會發現有很多命令都是相似的。</p><ul><li><code>DIR</code>– 顯示當前目錄的內容</li><li><code>CD</code> – 改變當前所在的目錄</li><li><code>COPY OLD.TXT NEW.TXT</code>– 複製文件</li><li><code>TYPE TEST.TXT</code> – 顯示文件內容</li><li><code>DEL TEST.TXT</code> – 刪除文件</li><li><code>XCOPY DIR NEWDIR</code> – 複製目錄及目錄下的所有內容</li><li><code>EDIT TEST.TXT</code>– 編輯一個文件</li><li><code>MKDIR NEWDIR</code> – 創建一個新目錄</li><li><code>CLS</code> – 清除屏幕</li></ul>',26)),o("p",null,[e[14]||(e[14]=t("你可以藉助互聯網或者 Jim Hall 所創建的 ",-1)),l(r,{href:"https://opensource.com/article/18/6/freedos-commands-cheat-sheet"},{default:s(()=>[...e[13]||(e[13]=[t("方便的速查表",-1)])]),_:1}),e[15]||(e[15]=t(" 來找到更多基本的 DOS 命令。",-1))]),e[42]||(e[42]=i('<h5 id="運行一個程序" tabindex="-1">運行一個程序 <a class="header-anchor" href="#運行一個程序" aria-label="Permalink to “運行一個程序”">​</a></h5><p>在 FreeDOS 上運行程序相當簡單。需要注意的是當你藉助 <code>fdimples</code> 軟件包管理器來安裝一個應用程序的時候，要確保你指定了待安裝程序的 .EXE 文件的路徑。這個路徑會在應用程序的詳細信息中顯示。要想運行程序，通常你還需要進入到程序所在文件夾並輸入該程序的名字。</p><p>例如，FreeDOS 中你可以安裝一個叫 <code>FED</code> 的編輯器。安裝完成後，你還需要做的就是進入 <code>C:\\FED</code> 這個文件夾下並輸入 <code>FED</code>。</p><p>對於位於 <code>\\bin</code> 這個文件夾的程序，比如 Pico。這些程序可以在任意文件夾中被調用。</p><p>對於遊戲通常會有一個或者兩個 .EXE 程序，你玩遊戲之前不得不先運行它們。這些設置文件通常能夠修復你遇到的聲音，視頻，或者控制問題。</p>',5)),o("p",null,[e[17]||(e[17]=t("如果你遇到一些本教程中沒指出的問題，別忘記訪問 ",-1)),l(r,{href:"http://www.freedos.org/"},{default:s(()=>[...e[16]||(e[16]=[t("FreeDOS 主站",-1)])]),_:1}),e[18]||(e[18]=t(" 來尋求解決辦法。他們有一個 wiki 和一些其他的支持選項。",-1))]),e[43]||(e[43]=o("p",null,"你使用過 FreeDOS 嗎？你還想看關於 FreeDOS 哪些方面的教程？請在下面的評論區告訴我們。",-1)),o("p",null,[e[20]||(e[20]=t("如果你覺得本篇文章很有趣，請花一分鐘的時間將它分享在你的社交媒體，Hacker News 或者 ",-1)),l(r,{href:"http://reddit.com/r/linuxusersgroup"},{default:s(()=>[...e[19]||(e[19]=[t("Reddit",-1)])]),_:1}),e[21]||(e[21]=t("。",-1))]),e[44]||(e[44]=o("hr",null,null,-1)),o("p",null,[e[23]||(e[23]=t("via: ",-1)),l(r,{href:"https://itsfoss.com/install-freedos/"},{default:s(()=>[...e[22]||(e[22]=[t("https://itsfoss.com/install-freedos/",-1)])]),_:1})]),o("p",null,[e[28]||(e[28]=t("作者：",-1)),l(r,{href:"https://itsfoss.com/author/john/"},{default:s(()=>[...e[24]||(e[24]=[t("John Paul",-1)])]),_:1}),e[29]||(e[29]=t(" 選題：",-1)),l(r,{href:"https://github.com/lujun9972"},{default:s(()=>[...e[25]||(e[25]=[t("lujun9972",-1)])]),_:1}),e[30]||(e[30]=t(" 譯者：",-1)),l(r,{href:"https://github.com/WangYueScream"},{default:s(()=>[...e[26]||(e[26]=[t("WangYueScream",-1)])]),_:1}),e[31]||(e[31]=t(" 校對：",-1)),l(r,{href:"https://github.com/wxy"},{default:s(()=>[...e[27]||(e[27]=[t("wxy",-1)])]),_:1})]),o("p",null,[e[34]||(e[34]=t("本文由 ",-1)),l(r,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...e[32]||(e[32]=[t("LCTT",-1)])]),_:1}),e[35]||(e[35]=t(" 原創編譯，",-1)),l(r,{href:"https://linux.cn/"},{default:s(()=>[...e[33]||(e[33]=[t("Linux中國",-1)])]),_:1}),e[36]||(e[36]=t(" 榮譽推出",-1))])])}const T=a(u,[["render",m]]);export{g as __pageData,T as default};
